(()=>{'use strict';
let filters={account:'',status:'',q:'',offset:0},generation=0;
const labels={issued:'بانتظار السداد',paid:'مدفوعة',cancelled:'ملغاة'};
const money=c=>(c/100).toLocaleString('ar-SA',{minimumFractionDigits:2,maximumFractionDigits:2})+' ريال';
const date=t=>new Date(t).toLocaleDateString('ar-SA',{calendar:'gregory',timeZone:'Asia/Riyadh'});
const accountOptions=selected=>'<option value="">جميع الحسابات</option>'+db.accounts.map(a=>`<option value="${esc(a.id)}" ${selected===a.id?'selected':''}>${esc(a.name)} · ${esc(a.id)}</option>`).join('');
const oldAdmin=adminHTML;
const oldRows=accountRows;accountRows=function(accounts){const html=oldRows(accounts);if(!serverMode||principal?.kind!=='admin')return html;return html.replace(/(<button[^>]+data-action="open-user"[^>]+data-id="([^"]+)"[^>]*>[^<]*<\/button>)/g,(_,button,id)=>button+`<button class="btn secondary small" data-invoice="account" data-account="${esc(id)}">الفواتير</button>`);};
adminHTML=function(){if(view!=='invoices')return oldAdmin();return head('إدارة الاشتراكات','الفواتير','فواتير شهرية وسنوية لكل حساب، مع سجل السداد والطباعة.', '<button class="btn primary" data-invoice="new">إصدار فاتورة ＋</button>')+`<section class="panel"><form id="invoice-filter" class="invoice-filters"><label class="field"><span>الحساب</span><select name="account">${accountOptions(filters.account)}</select></label><label class="field"><span>الحالة</span><select name="status"><option value="">جميع الحالات</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${filters.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>البحث</span><input name="q" value="${esc(filters.q)}" placeholder="رقم الفاتورة أو اسم العميل"></label><button class="btn secondary">بحث</button></form><div id="invoice-results" aria-live="polite">جارٍ تحميل الفواتير…</div></section><p class="sub mt">التفعيل أو التجديد المعتمد يصدر فاتورة مدفوعة تلقائيًا. إصدار فاتورة يدويًا أو اعتماد سدادها لا يفعّل الاشتراك. الفواتير هنا لخدمة الاشتراك وليست فواتير ضريبية.</p>`;};
async function refresh(){const run=++generation;try{const result=await api('/api/invoices?'+new URLSearchParams(filters));if(run!==generation||view!=='invoices'||role!=='admin')return;const target=document.querySelector('#invoice-results');if(!target)return;target.innerHTML=`<div class="invoice-totals"><div><small>المحصّل</small><strong>${money(result.summary.paidCents)}</strong></div><div><small>بانتظار السداد</small><strong>${money(result.summary.dueCents)}</strong></div><div><small>الفواتير المطابقة</small><strong>${fmt(result.total)}</strong></div></div><div class="table-wrap"><table><thead><tr><th>الفاتورة</th><th>الحساب</th><th>الباقة والفترة</th><th>المبلغ</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>${result.invoices.length?result.invoices.map(i=>`<tr><td><strong dir="ltr">${esc(i.number)}</strong><small>${date(i.created)}</small></td><td>${esc(i.customer)}<small>${esc(i.business)}</small></td><td>${esc(i.planName)} · ${i.period==='year'?'سنوي':'شهري'}<small>${date(i.start)} — ${date(i.end)}</small></td><td>${money(i.amountCents)}</td><td><span class="invoice-status ${i.status}">${labels[i.status]}</span></td><td><div class="invoice-actions"><a class="btn secondary small" target="_blank" rel="noopener" href="/invoice.html?id=${encodeURIComponent(i.id)}">عرض / طباعة</a>${i.status==='issued'?`<button class="btn primary small" data-invoice="paid" data-id="${esc(i.id)}">اعتماد السداد</button><button class="btn quiet small" data-invoice="cancel" data-id="${esc(i.id)}">إلغاء</button>`:''}</div></td></tr>`).join(''):'<tr><td colspan="6">لا توجد فواتير مطابقة. يمكنك إصدار أول فاتورة، وستظهر فواتير التجديدات الجديدة تلقائيًا.</td></tr>'}</tbody></table></div><div class="invoice-pagination"><button class="btn secondary small" data-invoice="prev" ${filters.offset===0?'disabled':''}>السابق</button><span>${result.total?Math.floor(filters.offset/50)+1:0} / ${Math.ceil(result.total/50)}</span><button class="btn secondary small" data-invoice="next" ${filters.offset+50>=result.total?'disabled':''}>التالي</button></div>`;}catch(e){const target=document.querySelector('#invoice-results');if(target)target.textContent=e.message;}}
const oldRender=render;render=function(){oldRender();if(!serverMode||publicPage||role!=='admin'||db.scopedBusiness)return;const nav=document.querySelector('.side-nav');if(nav&&!nav.querySelector('[data-invoice="open"]'))nav.insertAdjacentHTML('beforeend',`<button data-invoice="open" class="${view==='invoices'?'active':''}">${icon('card')}الفواتير</button>`);document.querySelectorAll('#account-rows tr').forEach(row=>{const open=row.querySelector('[data-action="open-user"]'),cell=row.lastElementChild;if(open&&cell&&!cell.querySelector('[data-invoice]'))cell.insertAdjacentHTML('beforeend',`<button class="btn secondary small" data-invoice="account" data-account="${esc(open.dataset.id)}">الفواتير</button>`);});if(view==='invoices')refresh();};
function newInvoice(){if(!db.accounts.length){toast('لا توجد حسابات لإصدار فاتورة.');return;}const a=db.accounts.find(a=>a.id===filters.account)||db.accounts[0],plan=a.subscription?.plan||'growth',period=a.subscription?.period||'month';modal('إصدار فاتورة اشتراك',`<form id="invoice-create"><input type="hidden" name="requestId" value="${crypto.randomUUID()}"><label class="field"><span>الحساب</span><select name="account" required>${accountOptions(a.id).replace('<option value="">جميع الحسابات</option>','')}</select></label><div class="form-row"><label class="field"><span>الباقة</span><select name="plan">${Object.values(RijaaPlans.plans).map(p=>`<option value="${p.id}" ${p.id===plan?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field"><span>مدة الاشتراك</span><select name="period"><option value="month" ${period==='month'?'selected':''}>شهري</option><option value="year" ${period==='year'?'selected':''}>سنوي · ١٢ شهرًا</option></select></label></div><div class="form-row"><label class="field"><span>المبلغ · ريال</span><input type="number" name="amount" required min="0" max="1000000" step="0.01" value="${period==='year'?RijaaPlans.plans[plan].annual:RijaaPlans.plans[plan].sale}"></label><label class="field"><span>بداية الفترة</span><input type="date" name="start" required value="${new Date().toISOString().slice(0,10)}"></label></div><label class="field"><span>ملاحظات · اختياري</span><textarea name="notes" maxlength="500" rows="2"></textarea></label><label class="terms"><input type="checkbox" name="paid"> تم استلام المبلغ واعتماد السداد</label><p class="sub">الإصدار لا يغيّر مدة الاشتراك. السنوي ١٢ شهرًا بالسعر السنوي المحدد.</p><div id="invoice-error" role="alert"></div><button class="btn primary full" type="submit">إصدار الفاتورة</button></form>`,'');}
document.addEventListener('change',e=>{const f=e.target.closest('#invoice-create');if(!f)return;if(e.target.name==='account'){const a=db.accounts.find(a=>a.id===e.target.value);f.elements.plan.value=a?.subscription?.plan||'growth';f.elements.period.value=a?.subscription?.period||'month';}if(['account','plan','period'].includes(e.target.name)){const p=RijaaPlans.plans[f.elements.plan.value];f.elements.amount.value=f.elements.period.value==='year'?p.annual:p.sale;}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-invoice]');if(!b)return;e.preventDefault();if(!serverMode||principal?.kind!=='admin')return;const action=b.dataset.invoice;if(action==='open'||action==='account'){filters={account:action==='account'?b.dataset.account:'',status:'',q:'',offset:0};view='invoices';role='admin';render();}else if(action==='new')newInvoice();else if(action==='prev'||action==='next'){filters.offset=Math.max(0,filters.offset+(action==='next'?50:-50));refresh();}else if(action==='paid'||action==='cancel'){modal(action==='paid'?'اعتماد سداد الفاتورة':'إلغاء الفاتورة',`<form id="invoice-status"><input type="hidden" name="id" value="${esc(b.dataset.id)}"><input type="hidden" name="action" value="invoice-${action}">${action==='paid'?'<p>أكد استلام المبلغ قبل اعتماد السداد. هذا الإجراء لا يفعّل الاشتراك.</p>':'<label class="field"><span>سبب الإلغاء</span><textarea name="reason" required maxlength="300"></textarea></label><p class="sub">تظل الفاتورة محفوظة في السجل بحالة ملغاة.</p>'}<div id="invoice-error" role="alert"></div><button type="submit" class="btn primary full">${action==='paid'?'تم استلام المبلغ · اعتماد':'تأكيد الإلغاء'}</button></form>`,'');}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['invoice-create','invoice-status','invoice-filter'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();const d=new FormData(f);if(f.id==='invoice-filter'){filters={account:d.get('account'),status:d.get('status'),q:d.get('q'),offset:0};refresh();return;}const button=f.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;try{const payload=f.id==='invoice-create'?{action:'invoice-create',account:d.get('account'),plan:d.get('plan'),period:d.get('period'),amount:Number(d.get('amount')),start:Date.parse(d.get('start')+'T12:00:00+03:00'),notes:d.get('notes'),paid:d.has('paid'),requestId:d.get('requestId')}:{action:d.get('action'),id:d.get('id'),reason:d.get('reason')};await serverCommand(payload,{redraw:false});document.querySelector('#modal').close();view='invoices';render();toast('تم حفظ الفاتورة.');}catch(error){f.querySelector('#invoice-error').textContent=error.message;button.disabled=false;}},true);
})();
